def forward(module, ids):
    table = module.table  # (vocab=21128, dim=512)
    ids = ids.long().view(-1)
    onehot = torch.zeros(ids.shape[0], table.shape[0], dtype=table.dtype, device=table.device)
    onehot.scatter_(1, ids.view(-1, 1), 1.0)
    return onehot @ table  # gemm: (tokens x vocab) @ (vocab x dim)
